const STORAGE_KEY='decision-log.v1';
const seed=[
 {id:'ADR-008',title:'Adoptar PostgreSQL como base de datos principal',status:'Aceptada',impact:'Alto',owner:'Equipo Backend',date:'2026-10-24',reviewDate:'2027-01-24',context:'El crecimiento de datos transaccionales y la necesidad de consultas complejas superaron las capacidades del almacenamiento actual.',rationale:'Estandarizar PostgreSQL 17 como motor relacional principal. Ofrece consistencia, un ecosistema maduro y capacidades operativas conocidas por el equipo.',alternatives:['MySQL — menor experiencia interna y extensibilidad más limitada.','MongoDB — el modelo documental no se ajusta a la mayoría de las relaciones del dominio.'],tags:['datos','arquitectura'],participants:'Backend, SRE, Data',review:''},
 {id:'ADR-007',title:'Estandarizar autenticación con OpenID Connect',status:'En revisión',impact:'Alto',owner:'Plataforma',date:'2026-10-18',reviewDate:'2026-11-12',context:'Cada producto implementa autenticación de forma distinta, generando deuda y riesgos de seguridad.',rationale:'Consolidar la identidad en OIDC y usar Authorization Code con PKCE para clientes públicos.',alternatives:['Mantener autenticación propia — multiplica el costo de auditoría.','SAML — adecuado para integraciones enterprise, pero menos simple para nuestros clientes.'],tags:['seguridad','plataforma'],participants:'Security, Plataforma, Web',review:''},
 {id:'ADR-006',title:'Migrar el frontend a un monorepo',status:'Propuesta',impact:'Medio',owner:'Web Platform',date:'2026-10-11',reviewDate:'2026-11-28',context:'Los repositorios independientes duplican configuración y hacen más lentos los cambios transversales.',rationale:'Evaluar un monorepo con workspaces para compartir configuración, componentes y pipelines.',alternatives:['Seguir con multirepo — menor cambio inicial, mayor costo de coordinación.','Submódulos Git — complejidad operativa innecesaria.'],tags:['frontend','developer-experience'],participants:'Web, Design Systems',review:''},
 {id:'ADR-005',title:'Usar eventos de dominio para integraciones internas',status:'Aceptada',impact:'Medio',owner:'Arquitectura',date:'2026-09-26',reviewDate:'2026-12-15',context:'Las integraciones síncronas generan dependencias fuertes y fallas en cascada.',rationale:'Publicar eventos de dominio versionados para casos donde la consistencia eventual sea aceptable.',alternatives:['REST síncrono para todo — acoplamiento temporal alto.','CDC generalizado — útil en datos, menos explícito a nivel de negocio.'],tags:['integraciones','arquitectura'],participants:'Arquitectura, Backend',review:''},
 {id:'ADR-004',title:'Retirar el servicio de generación de reportes legado',status:'Reemplazada',impact:'Bajo',owner:'Operaciones',date:'2026-09-03',reviewDate:'2026-10-03',context:'El servicio ya no recibe tráfico y depende de una versión sin soporte.',rationale:'Desactivarlo luego de verificar retención y exportar históricos.',alternatives:['Mantenerlo aislado — costo operativo sin beneficio.'],tags:['operaciones','deprecación'],participants:'Operaciones',review:'Retirado sin incidentes el 10/10/2026.'}
];
let decisions=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null')||seed;
let activeView='all',activeFilter='all',selectedId=null;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const fmt=d=>d?new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(d+'T12:00:00')):'—';
const initials=s=>(s||'Sin asignar').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
const statusClass=s=>({'Aceptada':'accepted','Propuesta':'proposed','En revisión':'reviewing','Reemplazada':'superseded'}[s]||'proposed');
const save=()=>localStorage.setItem(STORAGE_KEY,JSON.stringify(decisions));
const revisionOf=(d,reason)=>({at:new Date().toISOString(),reason,status:d.status,title:d.title,impact:d.impact,owner:d.owner,reviewDate:d.reviewDate,context:d.context,rationale:d.rationale,alternatives:[...(d.alternatives||[])],tags:[...(d.tags||[])],participants:d.participants,review:d.review||''});
const fmtTime=value=>value?new Intl.DateTimeFormat('es-AR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'—';
function stats(){
 const now=new Date(),limit=new Date();limit.setDate(now.getDate()+30);
 const review=decisions.filter(d=>d.reviewDate&&new Date(d.reviewDate+'T23:59:59')<=limit&&d.status!=='Reemplazada').length;
 const overdue=decisions.filter(d=>d.reviewDate&&new Date(d.reviewDate+'T23:59:59')<now&&d.status!=='Reemplazada').length;
 $('#allCount').textContent=decisions.length;$('#reviewCount').textContent=review;$('#statTotal').textContent=decisions.length;$('#statReview').textContent=review;$('#statAccepted').textContent=decisions.filter(d=>d.status==='Aceptada').length;
 $('#reviewHint').textContent=overdue?`${overdue} ${overdue===1?'vencida':'vencidas'}`:'Próximos 30 días';$('#reviewHint').style.color=overdue?'var(--red)':'';
}
function filtered(){
 const q=$('#searchInput').value.toLowerCase().trim();let list=decisions.filter(d=>[d.title,d.owner,d.context,d.rationale,(d.tags||[]).join(' ')].join(' ').toLowerCase().includes(q));
 if(activeView==='review'){const lim=new Date();lim.setDate(lim.getDate()+30);list=list.filter(d=>d.reviewDate&&new Date(d.reviewDate)<=lim&&d.status!=='Reemplazada')}
 if(activeView==='accepted')list=list.filter(d=>d.status==='Aceptada');if(activeView==='superseded')list=list.filter(d=>d.status==='Reemplazada');
 if(activeFilter!=='all')list=list.filter(d=>d.status===activeFilter);
 const sort=$('#sortSelect').value;return list.sort((a,b)=>sort==='review'?(a.reviewDate||'9999').localeCompare(b.reviewDate||'9999'):sort==='impact'?(['Alto','Medio','Bajo'].indexOf(a.impact)-['Alto','Medio','Bajo'].indexOf(b.impact)):b.date.localeCompare(a.date));
}
function render(){stats();const rows=$('#decisionRows'),list=filtered();const today=new Date().toISOString().slice(0,10);rows.innerHTML=list.map(d=>`<tr data-id="${d.id}"><td class="decision-cell"><strong>${esc(d.title)}</strong><span>${(d.tags||[]).map(tag => '#'+esc(tag)).join(' · ')}</span></td><td><span class="badge ${statusClass(d.status)}">${d.status}</span></td><td><span class="impact ${d.impact.toLowerCase()}">${d.impact}</span></td><td><span class="owner"><span class="owner-avatar">${initials(d.owner)}</span>${esc(d.owner||'Sin asignar')}</span></td><td class="date-muted">${fmt(d.date)}</td><td class="date-muted ${d.reviewDate&&d.reviewDate<today&&d.status!=='Reemplazada'?'overdue':''}">${fmt(d.reviewDate)}</td><td><button class="row-btn" aria-label="Ver ${esc(d.title)}">›</button></td></tr>`).join('');
 $('#emptyState').hidden=list.length>0;$$('#decisionRows tr').forEach(r=>r.addEventListener('click',()=>showDetail(r.dataset.id)));
}
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function showDetail(id){const d=decisions.find(x=>x.id===id);if(!d)return;selectedId=id;const history=[...(d.revisions||[])].reverse();$('#detailId').textContent=d.id+' · '+fmt(d.date);$('#detailTitle').textContent=d.title;$('#detailContent').innerHTML=`<div class="detail-meta"><span class="badge ${statusClass(d.status)}">${d.status}</span><span class="tag">Impacto ${d.impact.toLowerCase()}</span><span class="tag">${esc(d.owner||'Sin asignar')}</span></div><section class="detail-section"><h3>Contexto</h3><p>${esc(d.context)}</p></section><section class="detail-section"><h3>Decisión y fundamentos</h3><p>${esc(d.rationale)}</p></section><section class="detail-section"><h3>Alternativas consideradas</h3>${(d.alternatives||[]).map(a=>`<div class="alternative">${esc(a)}</div>`).join('')||'<p>No se documentaron alternativas.</p>'}</section><section class="detail-section"><h3>Seguimiento</h3><p><strong>Revisión:</strong> ${fmt(d.reviewDate)}<br><strong>Participantes:</strong> ${esc(d.participants||'—')}</p>${d.review?`<div class="alternative"><strong>Resultado de la revisión</strong><br>${esc(d.review)}</div>`:''}</section><section class="detail-section"><h3>Historial de cambios</h3>${history.length?`<div class="revision-timeline">${history.map((r,i)=>`<article class="revision-item"><span class="revision-dot"></span><div><div class="revision-head"><strong>${esc(r.reason||'Actualización')}</strong><time>${fmtTime(r.at)}</time></div><p><span class="badge ${statusClass(r.status)}">${esc(r.status)}</span> ${esc(r.title)}</p><small>${esc(r.owner||'Sin asignar')} · Impacto ${esc((r.impact||'—').toLowerCase())}${r.review?` · Revisión: ${esc(r.review)}`:''}</small></div></article>`).join('')}</div>`:'<p class="history-empty">Todavía no hay versiones anteriores. La próxima edición quedará registrada aquí.</p>'}</section><section class="detail-section"><h3>Etiquetas</h3><div class="tags">${(d.tags||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></section>`;$('#detailOverlay').hidden=false}
function openForm(d){$('#decisionForm').reset();$('#formTitle').textContent=d?'Editar decisión':'Nueva decisión';$('#decisionId').value=d?.id||'';['title','status','impact','owner','reviewDate','context','rationale','participants'].forEach(k=>$('#'+k).value=d?.[k]||'');$('#alternatives').value=(d?.alternatives||[]).join('\n');$('#tags').value=(d?.tags||[]).join(', ');$('#formOverlay').hidden=false}
function close(name){$('#'+name+'Overlay').hidden=true}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
$('#decisionForm').addEventListener('submit',e=>{e.preventDefault();const old=decisions.find(d=>d.id===$('#decisionId').value);const nextNum=Math.max(0,...decisions.map(d=>parseInt(d.id.split('-')[1])||0))+1;const d={id:old?.id||`ADR-${String(nextNum).padStart(3,'0')}`,title:$('#title').value.trim(),status:$('#status').value,impact:$('#impact').value,owner:$('#owner').value.trim(),date:old?.date||new Date().toISOString().slice(0,10),reviewDate:$('#reviewDate').value,context:$('#context').value.trim(),rationale:$('#rationale').value.trim(),alternatives:$('#alternatives').value.split('\n').map(x=>x.trim()).filter(Boolean),tags:$('#tags').value.split(',').map(x=>x.trim()).filter(Boolean),participants:$('#participants').value.trim(),review:old?.review||'',revisions:old?[...(old.revisions||[]),revisionOf(old,'Edición manual')]:[]};decisions=old?decisions.map(x=>x.id===old.id?d:x):[d,...decisions];save();render();close('form');toast(old?'Decisión actualizada con historial':'Decisión registrada')});
$('#newDecisionBtn').onclick=()=>openForm();$('#editBtn').onclick=()=>{const d=decisions.find(x=>x.id===selectedId);close('detail');openForm(d)};$('#deleteBtn').onclick=()=>{if(confirm('¿Eliminar esta decisión?')){decisions=decisions.filter(d=>d.id!==selectedId);save();render();close('detail');toast('Decisión eliminada')}};$('#reviewBtn').onclick=()=>{const d=decisions.find(x=>x.id===selectedId),result=prompt('¿Qué resultado tuvo la revisión?',d.review||'');if(result!==null){d.revisions=[...(d.revisions||[]),revisionOf(d,'Revisión programada')];d.review=result.trim();d.status='Aceptada';d.reviewDate='';save();render();showDetail(d.id);toast('Revisión registrada con historial')}};
$('#duplicateBtn').onclick=()=>{const source=decisions.find(x=>x.id===selectedId);if(!source)return;const nextNum=Math.max(0,...decisions.map(d=>parseInt(d.id.split('-')[1])||0))+1;const copy={...source,id:`ADR-${String(nextNum).padStart(3,'0')}`,title:`Copia de ${source.title}`,status:'Propuesta',date:new Date().toISOString().slice(0,10),reviewDate:'',review:'',revisions:[]};decisions=[copy,...decisions];save();render();close('detail');toast('Decisión duplicada como propuesta')};
$$('[data-close]').forEach(b=>b.onclick=()=>close(b.dataset.close));$$('.overlay').forEach(o=>o.addEventListener('click',e=>{if(e.target===o)o.hidden=true}));
$$('.nav-item[data-view]').forEach(b=>b.onclick=()=>{$$('.nav-item[data-view]').forEach(x=>x.classList.remove('active'));b.classList.add('active');activeView=b.dataset.view;render()});$$('.filter-tabs button').forEach(b=>b.onclick=()=>{$$('.filter-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');activeFilter=b.dataset.filter;render()});
function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function asMarkdown(){return decisions.map(d=>`# ${d.id} — ${d.title}\n\n- **Estado:** ${d.status}\n- **Impacto:** ${d.impact}\n- **Responsable:** ${d.owner||'Sin asignar'}\n- **Fecha:** ${d.date}\n- **Revisión:** ${d.reviewDate||'Sin programar'}\n\n## Contexto\n\n${d.context}\n\n## Decisión y fundamentos\n\n${d.rationale}\n\n## Alternativas\n\n${(d.alternatives||[]).map(a=>`- ${a}`).join('\n')||'- No documentadas'}\n\n## Resultado de revisión\n\n${d.review||'Pendiente'}\n\n## Historial de cambios\n\n${(d.revisions||[]).map(r=>`- **${r.at} — ${r.reason||'Actualización'}:** ${r.status}; responsable: ${r.owner||'Sin asignar'}; título: ${r.title}`).join('\n')||'- Sin versiones anteriores'}\n`).join('\n---\n\n')}
$('#searchInput').oninput=render;$('#sortSelect').onchange=render;$('#themeBtn').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('decision-log.theme',document.body.classList.contains('dark')?'dark':'light')};
$('#exportBtn').onclick=()=>{download('decision-log.json',JSON.stringify({version:1,exportedAt:new Date().toISOString(),decisions},null,2),'application/json');toast('Respaldo JSON generado')};
$('#markdownBtn').onclick=()=>{download('decision-log.md',asMarkdown(),'text/markdown');toast('Documento Markdown generado')};
$('#importBtn').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const parsed=JSON.parse(await file.text()),incoming=Array.isArray(parsed)?parsed:parsed.decisions;if(!Array.isArray(incoming)||!incoming.every(d=>d.id&&d.title&&d.status))throw new Error();if(confirm(`Se reemplazarán ${decisions.length} decisiones por ${incoming.length} del respaldo. ¿Continuar?`)){decisions=incoming;save();render();toast('Respaldo importado correctamente')}}catch{alert('El archivo no es un respaldo válido de Decision Log.')}e.target.value=''};
if(localStorage.getItem('decision-log.theme')==='dark')document.body.classList.add('dark');
render();
